packaging.specifiers._public_version:
def _public_version(version: Version) -> Version:
    if version.local is None:
        return version
    return version.__replace__(local=None)

packaging.version._validate_post:
def _validate_post(value: object, /) -> tuple[(Literal['post'], int)] | None:
    if value is None:
        return value
    if (isinstance(value, int) and value >= 0):
        return ('post', value)
    msg = f'post must be non-negative integer, got {value}'
    raise InvalidVersion(msg)

packaging.version._validate_local:
def _validate_local(value: object, /) -> LocalType | None:
    if value is None:
        return value
    if (isinstance(value, str) and _LOCAL_PATTERN.fullmatch(value)):
        return _parse_local_version(value)
    msg = f'local must be a valid version string, got {value!r}'
    raise InvalidVersion(msg)

packaging.version._validate_pre:
def _validate_pre(value: object, /) -> tuple[(Literal[('a', 'b', 'rc')], int)] | None:
    if value is None:
        return value
    if (isinstance(value, tuple) and len(value) == 2):
        (letter, number) = value
        letter = normalize_pre(letter)
        if (letter in {'a', 'b', 'rc'} and isinstance(number, int) and number >= 0):
            return (letter, number)
    msg = f"pre must be a tuple of ('a'|'b'|'rc', non-negative int), got {value}"
    raise InvalidVersion(msg)

packaging.markers._format_marker:
def _format_marker(marker: list[str] | MarkerAtom | str, first: bool | None = True) -> str:
    assert isinstance(marker, (list, tuple, str))
    if (isinstance(marker, list) and len(marker) == 1 and isinstance(marker[0], (list, tuple))):
        return _format_marker(marker[0])
    if isinstance(marker, list):
        inner = (_format_marker(m, first=False) for m in marker)
        if first:
            return ' '.join(inner)
        else:
            return '(' + ' '.join(inner) + ')'
    elif isinstance(marker, tuple):
        return ' '.join([m.serialize() for m in marker])
    else:
        return marker

packaging._manylinux._parse_elf:
@contextlib.contextmanager
def _parse_elf(path: str) -> Generator[(ELFFile | None, None, None)]:
    try:
        with open(path, 'rb') as f:
            yield ELFFile(f)
    except (OSError, TypeError, ValueError):
        yield None

packaging.specifiers._trim_release:
def _trim_release(release: tuple[(int, ...)]) -> tuple[(int, ...)]:
    """Strip trailing zeros from a release tuple for normalized comparison."""
    end = len(release)
    while (end > 1 and release[end - 1] == 0):
        end -= 1
    return (release if end == len(release) else release[:end])
